{
  "name": "CryoTel GT 低温制冷机",
  "name_en": "CryoTel GT cryocooler",
  "manufacturer": "Sunpower",
  "description": "CryoTel GT 是一款实验室低温制冷机，用于为低温实验提供受控冷量。它可按温度或功率设定运行，并可监测温度、功率、恒温模式、停止状态及故障信息，适合需要稳定低温环境的实验装置。",
  "description_en": "The CryoTel GT is a laboratory cryocooler used to provide controlled cooling for low-temperature experiments. It can operate with temperature or power setpoints and supports monitoring of temperature, power, thermostat mode, stop state, and fault conditions, making it suitable for setups that require a stable cryogenic environment.",
  "tag_hints": [
    "cryocooler",
    "cryogenic cooling",
    "low-temperature experiments",
    "temperature control",
    "power control",
    "thermostat mode",
    "cryogenic instrumentation"
  ],
  "actions": [
    {
      "action_name": "auto-at_temperature_band",
      "description": "获取/设置达到目标温度判定带宽。",
      "description_en": "Get/set the at-temperature band."
    },
    {
      "action_name": "auto-control_mode",
      "description": "获取/设置控制模式。",
      "description_en": "Get/set the control mode."
    },
    {
      "action_name": "auto-ki",
      "description": "获取/设置温度控制回路的积分常数。",
      "description_en": "Get/set the integral constant of the temperature control loop."
    },
    {
      "action_name": "auto-kp",
      "description": "获取/设置温度控制回路的比例常数。",
      "description_en": "Get/set the proportional constant of the temperature control loop."
    },
    {
      "action_name": "auto-power_max",
      "description": "获取/设置用户定义的最大功率。",
      "description_en": "Get/set the user-defined maximum power."
    },
    {
      "action_name": "auto-power_min",
      "description": "获取/设置用户定义的最小功率。",
      "description_en": "Get/set the user-defined minimum power."
    },
    {
      "action_name": "auto-power_setpoint",
      "description": "获取/设置功率设定值。",
      "description_en": "Get/set the power setpoint."
    },
    {
      "action_name": "auto-query",
      "description": "向制冷机控制器发送单条查询或设定命令并返回响应。",
      "description_en": "Send a single query or set command to the cryocooler controller and return the response."
    },
    {
      "action_name": "auto-query_multiline",
      "description": "向制冷机控制器发送返回多行数据的查询命令。",
      "description_en": "Send a query to the cryocooler controller that returns multiple lines of data."
    },
    {
      "action_name": "auto-reset",
      "description": "将制冷机恢复为出厂默认设置。",
      "description_en": "Reset the cryocooler to factory defaults."
    },
    {
      "action_name": "auto-save_control_mode",
      "description": "将当前控制模式保存为默认控制模式。",
      "description_en": "Save the current control mode as the default control mode."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向制冷机发送一条命令。",
      "description_en": "Send a command to the cryocooler."
    },
    {
      "action_name": "auto-stop",
      "description": "获取/设置停止状态。",
      "description_en": "Get/set the stop state."
    },
    {
      "action_name": "auto-stop_mode",
      "description": "获取/设置停止模式。",
      "description_en": "Get/set the stop mode."
    },
    {
      "action_name": "auto-temperature_setpoint",
      "description": "获取/设置温度设定值。",
      "description_en": "Get/set the temperature setpoint."
    },
    {
      "action_name": "auto-thermostat",
      "description": "获取/设置恒温模式。",
      "description_en": "Get/set the thermostat mode."
    },
    {
      "action_name": "auto-errors",
      "description": "获取当前活动错误代码。",
      "description_en": "Get the currently active error codes."
    },
    {
      "action_name": "auto-power",
      "description": "获取当前功率。",
      "description_en": "Get the current power."
    },
    {
      "action_name": "auto-power_current_and_limits",
      "description": "获取当前功率及允许的功率上下限。",
      "description_en": "Get the current power and the allowable power limits."
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号和修订版本。",
      "description_en": "Get the serial number and revision."
    },
    {
      "action_name": "auto-state",
      "description": "获取控制器状态和控制参数列表。",
      "description_en": "Get the controller state and list of control parameters."
    },
    {
      "action_name": "auto-temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    },
    {
      "action_name": "auto-thermostat_status",
      "description": "获取恒温模式状态。",
      "description_en": "Get the thermostat status."
    }
  ]
}

